"""
Cross-references firewall rules with active connections.
Flags any connection whose destination port isn't explicitly allowed
by an inbound rule for that source CIDR.
"""

import json
import csv
import ipaddress
from pathlib import Path


def parse_port_spec(port_spec):
    """Parse port specification, returns (start, end) tuple."""
    port_str = str(port_spec)
    if '-' in port_str:
        start, end = port_str.split('-', 1)
        return (int(start), int(end))
    else:
        port = int(port_str)
        return (port, port)


def port_matches(port, port_spec):
    """Check if port matches the port specification (single port or range)."""
    start, end = parse_port_spec(port_spec)
    return start <= int(port) <= end


def ip_in_cidr(ip_str, cidr_str):
    """Check if IP address is within the CIDR range."""
    try:
        ip = ipaddress.ip_address(ip_str)
        network = ipaddress.ip_network(cidr_str, strict=False)
        return ip in network
    except ValueError:
        return False


def get_prefix_len(cidr_str):
    """Get the prefix length of a CIDR (higher = more specific)."""
    try:
        network = ipaddress.ip_network(cidr_str, strict=False)
        return network.prefixlen
    except ValueError:
        return 0


def check_connection(src_ip, dest_port, rules, default_action='deny'):
    """
    Check if a connection is allowed by the firewall rules.
    Returns (is_blocked, matching_cidr) tuple.

    Logic:
    - Find all rules where src_ip matches the source_cidr
    - Sort by CIDR specificity (most specific first)
    - Check each rule in order; first rule where port matches determines outcome
    - If no rule matches the port, apply default action
    """
    # Find all rules that match this source IP
    matching_rules = []
    for rule in rules:
        if ip_in_cidr(src_ip, rule['source_cidr']):
            matching_rules.append(rule)

    # Sort by CIDR prefix length (most specific = highest prefix length first)
    matching_rules.sort(key=lambda r: get_prefix_len(r['source_cidr']), reverse=True)

    # Check rules in order of specificity
    for rule in matching_rules:
        if port_matches(dest_port, rule['dest_port']):
            if rule['action'] == 'allow':
                return (False, None)  # Allowed
            elif rule['action'] == 'deny':
                return (True, rule['source_cidr'])  # Explicitly blocked

    # No matching rule found - apply default action
    if default_action == 'deny':
        # Report the most specific CIDR that matched the IP
        if matching_rules:
            return (True, matching_rules[0]['source_cidr'])
        else:
            return (True, '0.0.0.0/0')

    return (False, None)


def main():
    audit_dir = Path('/home/user/audit')

    # Load firewall rules
    with open(audit_dir / 'firewall_rules.json', 'r') as f:
        fw_config = json.load(f)

    rules = fw_config.get('rules', [])
    default_action = fw_config.get('default_action', 'deny')

    # Load and check connections
    with open(audit_dir / 'connections.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            src_ip = row['src_ip']
            dest_port = int(row['dest_port'])

            is_blocked, blocking_cidr = check_connection(
                src_ip, dest_port, rules, default_action
            )

            if is_blocked:
                print(f"BLOCKED: {src_ip}:{dest_port} not allowed from {blocking_cidr}")


if __name__ == '__main__':
    main()


