from pathlib import Path


def load_firewall_rules(path):
    with open(path, 'r') as f:
        return json.load(f)


def load_connections(path):
    connections = []
    with open(path, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            connections.append(row)
    return connections


def ip_in_cidr(ip_str, cidr_str):
    try:
        ip = ipaddress.ip_address(ip_str)
        network = ipaddress.ip_network(cidr_str, strict=False)
        return ip in network
    except ValueError:
        return False


def get_prefix_length(cidr_str):
    try:
        network = ipaddress.ip_network(cidr_str, strict=False)
        return network.prefixlen
    except ValueError:
        return -1


def port_matches(port, port_spec):
    try:
        port = int(port)
        port_spec = str(port_spec)
        if '-' in port_spec:
            start, end = port_spec.split('-', 1)
            return int(start) <= port <= int(end)
        else:
            return port == int(port_spec)
    except (ValueError, TypeError):
        return False


def find_matching_rules(src_ip, rules):
    matching = []
    for rule in rules:
        cidr = rule.get('source_cidr', '')
        if ip_in_cidr(src_ip, cidr):
            prefix_len = get_prefix_length(cidr)
            matching.append((rule, prefix_len))
    matching.sort(key=lambda x: x[1], reverse=True)
    return matching


def check_connection(src_ip, dest_port, rules, default_action='deny'):
    matching_rules = find_matching_rules(src_ip, rules)

    if not matching_rules:
        return (default_action == 'allow', None, None)

    current_prefix = None
    rules_at_current_prefix = []

    for rule, prefix_len in matching_rules:
        if current_prefix is None:
            current_prefix = prefix_len

        if prefix_len != current_prefix:
            for r in rules_at_current_prefix:
                if port_matches(dest_port, r.get('dest_port', '')):
                    return (r['action'] == 'allow', r['source_cidr'], r)
            current_prefix = prefix_len
            rules_at_current_prefix = []

        rules_at_current_prefix.append(rule)

    for r in rules_at_current_prefix:
        if port_matches(dest_port, r.get('dest_port', '')):
            return (r['action'] == 'allow', r['source_cidr'], r)

    most_specific_cidr = matching_rules[0][0]['source_cidr'] if matching_rules else None
    return (default_action == 'allow', most_specific_cidr, None)


def main():
    base_path = Path('/home/user/audit')
    rules_path = base_path / 'firewall_rules.json'
    connections_path = base_path / 'connections.csv'

    firewall_data = load_firewall_rules(rules_path)
    rules = firewall_data.get('rules', [])
    default_action = firewall_data.get('default_action', 'deny')

    connections = load_connections(connections_path)

    for conn in connections:
        src_ip = conn.get('src_ip', '')
        dest_port = conn.get('dest_port', '')

        is_allowed, matched_cidr, matched_rule = check_connection(src_ip, dest_port, rules, default_action)

        if not is_allowed:
            if matched_cidr:
                print(f"BLOCKED: {src_ip}:{dest_port} not allowed from {matched_cidr}")
            else:
                print(f"BLOCKED: {src_ip}:{dest_port} not allowed (no matching CIDR)")


if __name__ == '__main__':
    main()


